create table if not exists public.athlete_experience_profiles (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,athlete_id uuid not null references public.athletes(id) on delete cascade,experience_mode text not null default 'standard',age_band text not null default '13_17',maturity_level text not null default 'guided',feature_profile jsonb not null default '{}'::jsonb,guardian_visibility boolean not null default true,coach_visibility boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,athlete_id));
create table if not exists public.athlete_experience_rules (id uuid primary key default gen_random_uuid(),tenant_id uuid references public.tenants(id) on delete cascade,sport_id uuid references public.sports(id) on delete cascade,code citext not null,name text not null,age_min integer,age_max integer,skill_band text,feature_key text not null,enabled boolean not null default true,configuration jsonb not null default '{}'::jsonb,priority integer not null default 100,created_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists public.athlete_challenges (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,sport_id uuid references public.sports(id) on delete set null,code citext not null,name text not null,description text,age_band text,challenge_type text not null,target_definition jsonb not null default '{}'::jsonb,reward_definition jsonb not null default '{}'::jsonb,starts_at timestamptz,ends_at timestamptz,active boolean not null default true,created_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists public.athlete_challenge_progress (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,athlete_id uuid not null references public.athletes(id) on delete cascade,challenge_id uuid not null references public.athlete_challenges(id) on delete cascade,progress_value numeric(12,4) not null default 0,target_value numeric(12,4),status text not null default 'active',evidence jsonb not null default '{}'::jsonb,completed_at timestamptz,updated_at timestamptz not null default now(),unique(athlete_id,challenge_id));
create table if not exists public.athlete_badges (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,code citext not null,name text not null,description text,age_band text,badge_definition jsonb not null default '{}'::jsonb,active boolean not null default true,created_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists public.athlete_badge_awards (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,athlete_id uuid not null references public.athletes(id) on delete cascade,badge_id uuid not null references public.athlete_badges(id) on delete cascade,awarded_by_person_id uuid references public.people(id) on delete set null,evidence jsonb not null default '{}'::jsonb,awarded_at timestamptz not null default now(),unique(athlete_id,badge_id));
create table if not exists public.athlete_streaks (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,athlete_id uuid not null references public.athletes(id) on delete cascade,streak_type text not null,current_count integer not null default 0,best_count integer not null default 0,last_activity_date date,metadata jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),unique(athlete_id,streak_type));
create table if not exists public.athlete_hub_events (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,athlete_id uuid not null references public.athletes(id) on delete cascade,event_type text not null,title text not null,body text,payload jsonb not null default '{}'::jsonb,visibility text not null default 'athlete',occurred_at timestamptz not null default now(),read_at timestamptz);
create index if not exists idx_athlete_experience_profiles_tenant_athlete on public.athlete_experience_profiles(tenant_id,athlete_id);
create index if not exists idx_athlete_challenge_progress_athlete_status on public.athlete_challenge_progress(athlete_id,status);
create index if not exists idx_athlete_badge_awards_athlete on public.athlete_badge_awards(athlete_id,awarded_at desc);
create index if not exists idx_athlete_hub_events_athlete_time on public.athlete_hub_events(athlete_id,occurred_at desc);
alter table public.athlete_experience_profiles enable row level security; alter table public.athlete_experience_rules enable row level security; alter table public.athlete_challenges enable row level security; alter table public.athlete_challenge_progress enable row level security; alter table public.athlete_badges enable row level security; alter table public.athlete_badge_awards enable row level security; alter table public.athlete_streaks enable row level security; alter table public.athlete_hub_events enable row level security;
create policy athlete_experience_profiles_access on public.athlete_experience_profiles for all to authenticated using (app.is_superuser() or tenant_id in (select app.current_tenant_ids())) with check (app.is_superuser() or tenant_id in (select app.current_tenant_ids()));
create policy athlete_experience_rules_access on public.athlete_experience_rules for all to authenticated using (app.is_superuser() or tenant_id is null or tenant_id in (select app.current_tenant_ids())) with check (app.is_superuser() or tenant_id in (select app.current_tenant_ids()));
create policy athlete_challenges_access on public.athlete_challenges for all to authenticated using (app.is_superuser() or tenant_id in (select app.current_tenant_ids())) with check (app.is_superuser() or tenant_id in (select app.current_tenant_ids()));
create policy athlete_challenge_progress_access on public.athlete_challenge_progress for all to authenticated using (app.is_superuser() or tenant_id in (select app.current_tenant_ids())) with check (app.is_superuser() or tenant_id in (select app.current_tenant_ids()));
create policy athlete_badges_access on public.athlete_badges for all to authenticated using (app.is_superuser() or tenant_id in (select app.current_tenant_ids())) with check (app.is_superuser() or tenant_id in (select app.current_tenant_ids()));
create policy athlete_badge_awards_access on public.athlete_badge_awards for all to authenticated using (app.is_superuser() or tenant_id in (select app.current_tenant_ids())) with check (app.is_superuser() or tenant_id in (select app.current_tenant_ids()));
create policy athlete_streaks_access on public.athlete_streaks for all to authenticated using (app.is_superuser() or tenant_id in (select app.current_tenant_ids())) with check (app.is_superuser() or tenant_id in (select app.current_tenant_ids()));
create policy athlete_hub_events_access on public.athlete_hub_events for all to authenticated using (app.is_superuser() or tenant_id in (select app.current_tenant_ids())) with check (app.is_superuser() or tenant_id in (select app.current_tenant_ids()));